func stop() {
    nextProcessor = nil
    isLooping = false
    loopCount = 0

    synchronizer.rate = 0
    if let timeObserver {
        synchronizer.removeTimeObserver(timeObserver)
        self.timeObserver = nil
    }

    if let loopingTask {
        loopingTask.cancel()
        self.loopingTask = nil
    }
}
